// 1. Obtém os dados do Webhook
const webhookData = $('Webhook Clientes').first().json.body;
let clientes = [];

if (webhookData && Array.isArray(webhookData.clientes)) {
  clientes = webhookData.clientes;
} else if (Array.isArray(webhookData)) {
  clientes = webhookData;
} else if (webhookData && typeof webhookData === 'object') {
  clientes = [webhookData];
}

// 2. Obtém o CSV de investimentos retornado pelo nó HTTP
const csvRaw = $input.first().json.data || $input.first().json;
const csvTexto = typeof csvRaw === 'string' ? csvRaw : (csvRaw.body || '');

// Parse simples e robusto do CSV
const linhasCsv = csvTexto.trim().split(/\r?\n/);
const cabecalho = linhasCsv[0].split(',').map(c => c.trim().toLowerCase());

const investimentos = [];
for (let i = 1; i < linhasCsv.length; i++) {
  const cols = linhasCsv[i].split(',').map(c => c.trim());
  if (cols.length >= 4) {
    investimentos.push({
      perfil: cols[0],
      produto: cols[1],
      minimo: parseFloat(cols[2]) || 0,
      rentabilidade: cols[3]
    });
  }
}

// 3. Função auxiliar para converter saldo string em float
function parseSaldo(saldoStr) {
  if (typeof saldoStr === 'number') return saldoStr;
  if (!saldoStr) return 0;
  const limpo = saldoStr.toString()
    .replace('R$', '')
    .replace(/\s/g, '')
    .replace(/\./g, '')
    .replace(',', '.');
  return parseFloat(limpo) || 0;
}

// 4. Cruzamento dos dados: Clientes x Investimentos
const resultado = clientes.map(cliente => {
  const saldoNum = cliente.saldo_numerico !== undefined ? cliente.saldo_numerico : parseSaldo(cliente.saldo);

  // Filtra produtos compatíveis com o perfil do cliente
  const produtosPerfil = investimentos.filter(inv => 
    inv.perfil.toLowerCase() === (cliente.perfil || '').toLowerCase()
  );

  // Filtra produtos onde o saldo é suficiente para o aporte mínimo
  const produtosAcessiveis = produtosPerfil.filter(inv => saldoNum >= inv.minimo);

  // Produtos que ultrapassam o saldo atual (para metas de expansão)
  const produtosParaMeta = produtosPerfil.filter(inv => saldoNum < inv.minimo);

  return {
    cliente: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      saldo_numerico: saldoNum,
      perfil: cliente.perfil
    },
    produtos_recomendados: produtosAcessiveis.length > 0 ? produtosAcessiveis : produtosPerfil,
    produtos_futuros: produtosParaMeta,
    total_opcoes_compativeis: produtosAcessiveis.length
  };
});

return resultado.map(item => ({ json: item }));

// Gera mensagens personalizadas consultivas para cada cliente
const itens = $input.all();

const resultados = itens.map(item => {
  const data = item.json;
  const c = data.cliente;
  const prods = data.produtos_recomendados || [];

  let saudacao = `Olá, ${c.nome}! Preparamos uma análise financeira exclusiva para você.`;
  let resumoPerfil = '';

  if (c.perfil.toLowerCase() === 'conservador') {
    resumoPerfil = 'Como seu perfil é Conservador, priorizamos liquidez, segurança patrimonial e previsibilidade de retornos.';
  } else if (c.perfil.toLowerCase() === 'moderado') {
    resumoPerfil = 'Como seu perfil é Moderado, buscamos o equilíbrio ideal entre preservação de capital e rentabilidades superiores à inflação.';
  } else {
    resumoPerfil = 'Como seu perfil é Arrojado, seu foco está em potencial de valorização expressiva e estratégias ativas de mercado.';
  }

  const listaFormatada = prods.map(p => 
    `- ${p.produto}: Rentabilidade de ${p.rentabilidade} (Aporte mínimo: R$ ${p.minimo.toLocaleString('pt-BR', { minimumFractionDigits: 2 })})`
  ).join('\n');

  let mensagemCompleta = `${saudacao}\n\n${resumoPerfil}\n\nCom base no seu saldo disponível de ${c.saldo}, selecionamos as seguintes opções sob medida:\n${listaFormatada}\n\n💡 Recomendação do Consultor: Mantenha sempre sua disciplina de aportes mensais para maximizar seus juros compostos. Conte conosco para tirar dúvidas!`;

  return {
    json: {
      cliente_nome: c.nome,
      cliente_email: c.email,
      perfil: c.perfil,
      saldo: c.saldo,
      total_produtos: prods.length,
      produtos: prods,
      mensagem_personalizada: mensagemCompleta,
      timestamp: new Date().toISOString()
    }
  };
});

return resultados;
